                // Go's single-threaded work group runs queued functions last-queued first.
                source_files.iter().enumerate().rev().for_each(|(i, &file)| run(i, file));
            } else {
                worker_pool().install(|| {
                    source_files.par_iter().enumerate().for_each(|(i, &file)| run(i, file));
                });
