# Interleaved A/B: wall, user+sys CPU, peak RSS of `extract` per binary and corpus; JSON compared with `stats` dropped.
# usage: bench.py RUNS OUTDIR name=binary[:ENV=VAL,...] ... -- corpus_dir ...
import json, os, statistics, subprocess, sys, time, resource

runs = int(sys.argv[1]); outdir = sys.argv[2]
sep = sys.argv.index('--')
variants = []
for spec in sys.argv[3:sep]:
    name, rest = spec.split('=', 1)
    binary, _, envs = rest.partition(':')
    env = dict(e.split('=', 1) for e in envs.split(',') if e)
    variants.append((name, binary, env))
corpora = sys.argv[sep + 1:]
os.makedirs(outdir, exist_ok=True)


def bad_semantic(doc):
    found = []
    def walk(x):
        if isinstance(x, dict):
            if x.get('code') in ('SEMANTIC_BACKEND', 'SemanticBackend', 'semantic_backend') and str(x.get('severity', '')).lower() != 'info':
                found.append((x.get('code'), x.get('severity')))
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    walk(doc)
    return found


def strip(doc):
    if isinstance(doc, dict):
        return {k: strip(v) for k, v in doc.items() if k != 'stats'}
    if isinstance(doc, list):
        return [strip(v) for v in doc]
    return doc


results = {}
for corpus in corpora:
    label = corpus.rstrip('/').split('/repos/')[-1].split('/')[0]
    reference = None
    for r in range(runs):
        for name, binary, env in variants:
            out = f'{outdir}/{label}-{name}-{r}.json'
            load = os.getloadavg()[0]
            cmd = ['/usr/bin/time', '-l', binary, 'extract', '--src', corpus, '--quiet', '--no-cache', '--load-dependencies', '--json']
            t0 = time.monotonic()
            p = subprocess.run(cmd, stdout=open(out, 'w'), stderr=subprocess.PIPE, text=True, env={**os.environ, **env})
            wall = time.monotonic() - t0
            err = p.stderr
            def field(key):
                for line in err.splitlines():
                    if line.strip().endswith(key):
                        return int(line.split()[0])
                return 0
            words = err.split()
            user = float(words[words.index('user') - 1]); sys_ = float(words[words.index('sys') - 1])
            rss = field('maximum resident set size') / 2**20
            ivcsw = field('involuntary context switches')
            doc = json.load(open(out))
            bad = bad_semantic(doc)
            same = None
            s = strip(doc)
            if reference is None:
                reference = s
            else:
                same = s == reference
            results.setdefault((label, name), []).append(dict(wall=wall, cpu=user + sys_, user=user, sys=sys_, rss=rss, ivcsw=ivcsw, bad=bad, same=same, exit=p.returncode, load=load))
            print(f'{label:14} {name:10} r{r} exit={p.returncode} wall={wall:6.2f} cpu={user + sys_:6.2f} (u{user:.2f} s{sys_:.2f}) rss={rss:7.1f}MiB ivcsw={ivcsw} load={load:.1f} same={same} bad={bad[:2]}', flush=True)
            if r > 0 or name != variants[0][0]:
                os.remove(out)

print('\n== medians (runs with a non-info SEMANTIC_BACKEND dropped)')
for (label, name), rs in results.items():
    ok = [x for x in rs if not x['bad'] and x['exit'] == 0]
    if not ok:
        print(f'{label:14} {name:10} no clean runs'); continue
    med = lambda k: statistics.median(x[k] for x in ok)
    diff = sum(1 for x in rs if x['same'] is False)
    print(f'{label:14} {name:10} n={len(ok)} wall={med("wall"):6.2f} cpu={med("cpu"):6.2f} rss={med("rss"):7.1f} ivcsw={med("ivcsw"):8.0f} output_differs_in={diff}')

