# Aggregate a macOS `sample` call graph: self samples by thread pool, category and pipeline stage.
import re, sys, collections

lines = open(sys.argv[1], errors='replace').read().split('\n')
start = next(i for i, l in enumerate(lines) if l.startswith('Call graph:'))
end = next(i for i in range(start, len(lines)) if lines[i].startswith('Total number in stack'))
node_re = re.compile(r'^[\s+!:|]*?(\d+)\s+(.*)$')

CATS = [
    ('sleep/park', ['__psynch_cvwait', '__psynch_mutexwait', '__ulock_wait', 'kevent', 'semaphore_wait', '__semwait', 'mach_msg', '__select', '__poll', 'nanosleep', '__workq_kernreturn']),
    ('yield/spin', ['swtch_pri', 'sched_yield', 'thread_switch', 'yield_now', 'spin_loop', '__psynch_cvsignal', '__psynch_cvbroad', '__ulock_wake', 'pthread_yield']),
    ('rayon-steal', ['crossbeam', 'rayon_core']),
    ('alloc', ['mi_', 'mimalloc', '_malloc', '_free', 'madvise', '__bzero', '_platform_memset', 'realloc', '_mm_']),
    ('memcpy', ['memmove', 'memcpy']),
    ('fs-syscall', ['lstat', 'stat', '__open', 'getdirentries', '__close', '__read', '__pread', 'realpath', 'getattrlist', 'fstat', '__mmap', '__munmap', 'access']),
]
STAGES = [
    ('caliper:parse', ['Indexed5build', 'parse_source_file', 'AmbientDts']),
    ('caliper:deps', ['dependency_types']),
    ('caliper:resolve', ['resolve_guarded', 'resolver']),
    ('caliper:interned/merge', ['interned', 'merge_semantic', 'syntax']),
    ('tsrs:parse', ['filesparser', 'fileloader']),
    ('tsrs:bind', ['fileregions', 'binder']),
    ('tsrs:check', ['tsrs_checker', 'checkerpool']),
    ('tsrs:other', ['tsrs_']),
]


def cat_of(n):
    for c, pats in CATS:
        if any(p in n for p in pats):
            return c
    return 'work'


def stage_of(path):
    for s, pats in STAGES:
        if any(p in f for f in path for p in pats):
            return s
    return 'other'


samples = []  # (thread, path list, leaf, self)
stack = []
thread = None


def pop():
    ind, c, n, cs = stack.pop()
    if c - cs > 0:
        samples.append((thread, [x[2] for x in stack] + [n], n, c - cs))


for l in lines[start + 1:end]:
    m = node_re.match(l)
    if not m:
        continue
    indent = len(l) - len(l.lstrip(' +!:|'))
    count, name = int(m.group(1)), m.group(2)
    if name.startswith('Thread_'):
        while stack:
            pop()
        thread = name
        continue
    while stack and stack[-1][0] >= indent:
        pop()
    if stack:
        stack[-1] = (stack[-1][0], stack[-1][1], stack[-1][2], stack[-1][3] + count)
    stack.append((indent, count, name, 0))
while stack:
    pop()

# Classify each thread by what runs on it.
names = collections.defaultdict(set)
for t, path, leaf, n in samples:
    names[t].update(path)


def pool_of(t):
    if 'main-thread' in t:
        return 'main'
    for k in ['tokio', 'caliper-checker', 'caliper-early', 'caliper-drop', 'caliper-deps', 'project-timers']:
        if any(k in f for f in names[t]) or k in t:
            return k
    blob = ' '.join(names[t])
    if 'rayon_core' in blob:
        return 'tsrs-pool' if 'tsrs_' in blob and 'caliper_docgen_core' not in blob else ('caliper-pool' if 'caliper_docgen_core' in blob and 'tsrs_' not in blob else 'rayon-mixed')
    return 'other'


pools = {t: pool_of(t) for t in names}
print('threads per pool', collections.Counter(pools.values()))
bycat = collections.Counter(); bystage = collections.Counter(); leaves = collections.Counter()
for t, path, leaf, n in samples:
    p = pools[t]; c = cat_of(leaf)
    bycat[(p, c)] += n
    if c != 'sleep/park':
        bystage[(p, stage_of(path), c)] += n
        leaves[(p, re.sub(r'\s+\(in .*', '', leaf)[:90])] += n
print('== pool x category (sleep/park is off-CPU)')
for k, v in sorted(bycat.items(), key=lambda kv: (kv[0][0], -kv[1])):
    print(f'{v:7} {k[0]:16} {k[1]}')
print('== on-CPU by pool x stage x category')
for k, v in sorted(bystage.items(), key=lambda kv: (kv[0][0], kv[0][1], -kv[1])):
    if v >= int(sys.argv[3]) if len(sys.argv) > 3 else 5:
        print(f'{v:7} {k[0]:16} {k[1]:24} {k[2]}')
print('== top on-CPU leaves')
for k, v in leaves.most_common(int(sys.argv[2]) if len(sys.argv) > 2 else 30):
    print(f'{v:7} {k[0]:16} {k[1]}')

